import{z as o,x as l,o as r,c as p,q as i,j as t,D as e,d as a,s as A,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"完美贝叶斯与信号精炼","description":"","frontmatter":{"title":"完美贝叶斯与信号精炼","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/perfect-bayesian.md","filePath":"econ/perfect-bayesian.md","lastUpdated":1791063341000}'),m={name:"econ/perfect-bayesian.md"};function d(F,E,u,c,C,h){const n=l("Mermaid");return r(),p("div",null,[E[2]||(E[2]=i('<h1 id="完美贝叶斯与信号精炼" tabindex="-1">完美贝叶斯与信号精炼 <a class="header-anchor" href="#完美贝叶斯与信号精炼" aria-label="Permalink to &quot;完美贝叶斯与信号精炼&quot;">​</a></h1><div class="epigraph"><p>均衡必须在每个信息集上给出信念，策略在该信念下最优，信念在路径上由贝叶斯法则更新。</p><footer>—— 据 Kreps and Wilson, Sequential Equilibria, Econometrica, 1982；Fudenberg and Tirole, JET, 1991 整理</footer></div><p><a href="/econ/bayesian-nash">上一课</a>（不完全信息与贝叶斯纳什）。的 BNE 把类型写进策略，但不约束零概率信息集。信号博弈里，接收者看见一个「不该出现」的行动，后验随便写，可以撑住「我若偏离你就当成最坏类型」的恐吓。缺口是：给每个信息集配上信念，并要求策略在这些信念下序贯理性。本课钉完美贝叶斯均衡（PBE）的最低要求，并指出它仍太松，为柠檬与发送信号做准备。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扩展式加类型之后，许多信息集不是子博弈的根（信息集不是单点）。SPE 用不上。<a href="/econ/subgame-perfect">子博弈完美</a>删空威胁的那把刀，在这里不够。Kreps–Wilson 的序贯均衡用颤抖生成处处正概率，再取极限，得到策略与信念的一对 \\((\\sigma,\\mu)\\)。教科书里的 PBE 弱一点：路径上贝叶斯，路径外信念任意但策略对该信念最优。</p><p>最低两条：（1）序贯理性：在每一信息集，给定 \\(\\mu\\) 与他人策略，行动是最佳应答；（2）路径上的 \\(\\mu\\) 由 \\(\\sigma\\) 与先验经贝叶斯得到。<span class="marginnote">术语翻译：这两条合起来像「配了案卷的侦探」——\\(\\mu\\) 是案卷（在每个信息集上写明「大概率是谁在行动」），序贯理性是「按当前案卷选最优动作」。BNE 的毛病是零概率信息集上没有案卷只能瞎猜；缺第二条则是拿着案卷不肯更新，推理自相矛盾。</span>缺（1）会回到不可信；缺（2）会让人「看见发生了的事却不更新」。</p><h3 id="pbe-仍允许很怪的路径外信念" tabindex="-1">PBE 仍允许很怪的路径外信念 <a class="header-anchor" href="#pbe-仍允许很怪的路径外信念" aria-label="Permalink to &quot;PBE 仍允许很怪的路径外信念&quot;">​</a></h3><p>偏离若是零概率，贝叶斯没有定义。接收者可以把偏离全归给高成本类型，从而吓阻发送者。Cho–Kreps 直觉标准等，用「谁更想偏离」来砍这些信念，本课只点名，不展开精炼族。柠檬与 Spence 会碰到分离、混同、以及靠怪信念撑住的混同。</p><p><span class="marginnote">信号博弈时序：自然抽类型 → 知情者发信号 → 接收者在信息集上形成 \\(\\mu\\)，选行动。分离：不同类型发不同信号，路径上信念退化到真类型。混同：信号无信息，\\(\\mu\\) 停在先验。</span></p><p>弱 PBE 允许路径外任意 \\(\\mu\\)；序贯均衡用颤抖极限把 \\(\\mu\\) 也管住。 主干后课用弱 PBE 算柠檬与 Spence，需要砍时再点直觉标准。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：有限类型、有限信号与行动的扩展式。解概念：PBE。计算常先猜分离或混同，再反推使激励相容成立的信念与行动，最后检查路径外：若某信号无人发，指定一个 \\(\\mu\\)，使无人想改发这个信号。</p><p>序贯均衡要求路径外信念也是颤抖极限，比任意 PBE 紧。主干后课用 PBE 说话即可；需要砍均衡时再引直觉标准。</p>',13)),(r(),t(s,null,{default:e(()=>[A(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20BNE%5B%22BNE%EF%BC%9A%E4%B8%8D%E7%AE%A1%E9%9B%B6%E6%A6%82%E7%8E%87%E4%BF%A1%E6%81%AF%E9%9B%86%22%5D%20--%3E%20PBE%5B%22(%CF%83%2C%20%CE%BC)%EF%BC%9A%E5%BA%8F%E8%B4%AF%E7%90%86%E6%80%A7%20%2B%20%E8%B7%AF%E5%BE%84%E8%B4%9D%E5%8F%B6%E6%96%AF%22%5D%0A%20%20PBE%20--%3E%20SEQ%5B%22%E5%BA%8F%E8%B4%AF%E5%9D%87%E8%A1%A1%EF%BC%9A%E9%A2%A4%E6%8A%96%E6%9E%81%E9%99%90%22%5D%0A%20%20PBE%20--%3E%20LOOSE%5B%22%E8%B7%AF%E5%BE%84%E5%A4%96%20%CE%BC%20%E4%BB%8D%E8%87%AA%E7%94%B1%22%5D%0A%20%20PBE%20--%3E%20MKT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%B8%82%E5%9C%BA%E9%87%8C%E7%9A%84%E9%9A%90%E8%97%8F%E7%B1%BB%E5%9E%8B%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("信念是接收者决策的状态变量。没有 \\(\\mu\\)，说「看见信号后选 \\(a\\)」没有概率论证。"),B("span",{class:"marginnote"},"数字实例：分离均衡里高成本类型发贵信号、低成本发便宜信号，先验各 50%。接收者看见贵信号，贝叶斯给出 \\(P(\\text{高}\\mid\\text{贵})=\\frac{0.5\\times 1}{0.5\\times 1+0.5\\times 0}=1\\)——后验 100% 指向高成本。混同均衡里两类发同一个信号，信号不带信息，\\(\\mu\\) 停在先验的 50% 不动。"),a("路径上贝叶斯保证均衡自我一致：你用来吓我的那条后验，不能与你自己的策略矛盾。路径外的自由，则是恐吓的剩余空间——精炼要砍的正是这块。")],-1)),(r(),t(s,null,{default:e(()=>[A(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAT%5B%22%E8%87%AA%E7%84%B6%E6%8A%BD%E7%B1%BB%E5%9E%8B%3A%20%E9%AB%98%E6%88%90%E6%9C%AC%E6%88%96%E4%BD%8E%E6%88%90%E6%9C%AC%22%5D%20--%3E%20SIG%5B%22%E5%8F%91%E9%80%81%E8%80%85%E9%80%89%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20SIG%20--%3E%20REC%5B%22%E6%8E%A5%E6%94%B6%E8%80%85%E5%9C%A8%E4%BF%A1%E6%81%AF%E9%9B%86%E4%B8%8A%E6%8C%81%20%CE%BC%22%5D%0A%20%20REC%20--%3E%20ACT%5B%22%E6%8C%89%20%CE%BC%20%E9%80%89%E8%A1%8C%E5%8A%A8%20a(m)%22%5D%0A%20%20ACT%20--%3E%20DEV%5B%22%E6%9F%90%E7%B1%BB%E5%9E%8B%E6%83%B3%E5%81%8F%E7%A6%BB%E5%88%B0%E6%97%A0%E4%BA%BA%E5%8F%91%E7%9A%84%E4%BF%A1%E5%8F%B7%20m'%22%5D%0A%20%20DEV%20--%3E%20OFF%5B%22%E8%B7%AF%E5%BE%84%E5%A4%96%E4%BF%A1%E6%81%AF%E9%9B%86%3A%20%E8%B4%9D%E5%8F%B6%E6%96%AF%E6%97%A0%E5%AE%9A%E4%B9%89%2C%20%CE%BC%20%E4%BB%BB%E6%84%8F%22%5D%0A%20%20OFF%20--%3E%20BLUFF%5B%22%E6%8A%8A%20m'%20%E6%A0%BD%E8%B5%83%E7%BB%99%E6%9C%80%E5%9D%8F%E7%B1%BB%E5%9E%8B%2C%20%E5%9B%9E%E5%BA%94%E6%9C%80%E7%8B%A0%22%5D%0A%20%20BLUFF%20--%3E%20HOLD%5B%22%E5%81%8F%E7%A6%BB%E6%97%A0%E5%88%A9%E5%8F%AF%E5%9B%BE%2C%20%E5%9D%87%E8%A1%A1%E8%A2%AB%E6%80%AA%E4%BF%A1%E5%BF%B5%E6%92%91%E4%BD%8F%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p>上图回答的问题是「怪信念具体怎么撑住一个均衡」：解概念阶梯图给出定义的强弱排序，这张画出恐吓的传导链——偏离是零概率事件，贝叶斯在那里无话可说，接收者把栽赃写进 \\(\\mu\\) 就能让任何偏离都不划算；直觉标准等精炼砍的正是这条链的第 6、7 节。</p><p>与完全信息 SPE 的连续性：若类型退化成一点，PBE 回到 SPE。不完全信息多出来的，全是信念。后课市场失灵不是新的均衡定义，而是把类型读成质量、生产率、风险，把信号读成价格、教育、合同菜单。柠檬将只用价格这一维信号；Spence 让知情者先选有成本的 \\(e\\)。两课都在 PBE 里算分离与混同，不再改解概念。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>PBE 定义在文献里不完全统一（Fudenberg–Tirole 对多期有额外「不得用无关类型的信息」等）。应用时写清：路径贝叶斯、序贯理性、以及路径外信念的限制（若有）。<span class="marginnote">常见误区：初学者看到「路径外信念任意」就以为 PBE 可以乱写一气。自由度只在于「用哪个信念去撑均衡」，策略必须对这个信念序贯理性——于是同一博弈常有多个 PBE，精炼（直觉标准、序贯均衡）的工作就是把靠荒唐信念撑住的那些筛掉。</span>连续信号空间的偏离更难指定 \\(\\mu\\)。</p><p>多期信号还要求不能用「与该信息集无关的类型」去编后验，否则 PBE 的定义要按 Fudenberg–Tirole 加限制。主干后课用静态信号博弈，不踩这条。</p><p>后课默认：隐藏类型、可观察行动的互动，解是 PBE；混同与分离是候选，怪信念撑住的混同视为脆弱。</p><h3 id="先猜分离或混同-再给路径外指定信念" tabindex="-1">先猜分离或混同，再给路径外指定信念 <a class="header-anchor" href="#先猜分离或混同-再给路径外指定信念" aria-label="Permalink to &quot;先猜分离或混同，再给路径外指定信念&quot;">​</a></h3><p>算均衡时先猜分离或混同，反推激励相容，再给无人发送的信号指定 \\(\\mu\\)，使无人想改发。这不是新定义，是 PBE 的常规算法。柠檬几乎只有混同（一个价格）；Spence 两种都算。Cho–Kreps 直觉标准再砍「低类型更不想发的偏离被栽赃给低类型」的混同，本课只点名。Kreps–Wilson 序贯均衡用颤抖给路径外信念一个极限来源，比任意 PBE 紧。</p><p>多期信号还要求不能用「与该信息集无关的类型」去编后验，否则定义要按 Fudenberg–Tirole 加限制。主干后课用静态信号博弈。</p><p><span class="marginnote">接收者策略是 \\(a(m)\\)，发送者预见到 \\(a\\) 与 \\(\\mu\\)。没有成对的 \\((\\sigma,\\mu)\\)，「看见 \\(m\\) 之后选 \\(a\\)」没有概率论证。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BNE 不够；PBE 给每个信息集信念，并要求序贯理性。</li><li>路径上必须贝叶斯；路径外信念默认自由，故 PBE 仍松。</li><li>分离与混同是信号博弈的两类候选。</li><li>更强精炼（序贯、直觉标准）用来砍怪信念。</li><li>出处：Kreps and Wilson, <em>Econometrica</em> 1982；Fudenberg and Tirole, <em>JET</em> 1991。</li></ul>',12))])}const b=o(m,[["render",d]]);export{D as __pageData,b as default};
